#include <iostream>
struct Node { int data; Node* next; };
int main() {
    Node* head = new Node{10, new Node{20, nullptr}};
    for (Node* cur = head; cur != nullptr; cur = cur->next)
        std::cout << cur->data << ' ';
    while (head != nullptr) {
        Node* old = head;
        head = head->next;
        delete old;
    }
}

#include <iostream>
#include <stack>
int main() {
    std::stack<int> s;
    s.push(10);
    s.push(20);
    if (!s.empty()) {
        std::cout << s.top() << '\n';
        s.pop();
    }
    std::cout << s.top() << '\n';
}

